import csv, os
path = params.get('path') or params.get('file') or ''
if not path:
    result = {'error': 'pass params.path (absolute CSV file path)'}
elif not os.path.isabs(path):
    result = {'error': 'path must be absolute', 'received': path}
elif not os.path.isfile(path):
    result = {'error': 'file not found', 'path': path}
elif os.path.getsize(path) > 50 * 1024 * 1024:
    result = {'error': 'file > 50MB; trim before passing through this skill', 'path': path, 'size': os.path.getsize(path)}
else:
    delimiter = params.get('delimiter') or ','
    try:
        with open(path, 'r', encoding='utf-8', newline='') as f:
            reader = csv.reader(f, delimiter=delimiter)
            headers = next(reader, [])
            row_count = sum(1 for _ in reader)
        result = {
            'path': path,
            'headers': headers,
            'column_count': len(headers),
            'row_count': row_count,
            'delimiter': delimiter,
        }
    except UnicodeDecodeError:
        result = {'error': 'not UTF-8 — re-save the CSV as UTF-8 or pass params.encoding (not yet supported)'}
    except Exception as e:
        result = {'error': f'csv parse failed: {e}', 'path': path}
